// Loopback-only HTTPS origin for the original, content-addressed candidate bytes.
// Product API responses are generated by Next, including its regular verification.
import { createServer } from 'node:https';
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const [root, keyFile, certFile, port = '3443', auditedStore] = process.argv.slice(2);
const upstream = new URL(process.env.NEXT_PUBLIC_SUPABASE_URL);
const secret = process.env.SUPABASE_SECRET_KEY;
if (!root || !keyFile || !certFile || !secret || upstream.protocol !== 'https:') {
  throw new Error('Expected a candidate directory, local TLS key and certificate, and the existing Storage environment');
}
const candidate = /^\/storage\/v1\/object\/pra-climate-archives\/(forecast-masks\/(?:blobs|indexes|geometries)\/[a-f0-9]{64}\.json\.gz)$/;
const weather = /^\/storage\/v1\/object\/pra-climate-archives\/weather\/([a-f0-9]{64}\.json\.gz)$/;
async function exactBytes(directory, path) {
  if (!path || !directory) return undefined;
  return readFile(resolve(directory, path)).catch(error => {
    if (error.code === 'ENOENT') return undefined;
    throw error;
  });
}

createServer({ key: await readFile(keyFile), cert: await readFile(certFile) }, async (request, response) => {
  try {
    if (request.method !== 'GET' || request.headers.apikey !== secret ||
        !request.url?.startsWith('/storage/v1/object/pra-climate-archives/')) {
      response.writeHead(404).end();
      return;
    }
    const path = candidate.exec(request.url)?.[1];
    const bytes = await exactBytes(root, path) ?? await exactBytes(auditedStore, path) ??
      await exactBytes(auditedStore, weather.exec(request.url)?.[1]);
    if (bytes) {
      response.writeHead(200, {'Content-Length': bytes.length}).end(bytes);
      return;
    }
    const source = await fetch(new URL(request.url, upstream), {
      headers: {apikey: secret}, redirect: 'error', signal: AbortSignal.timeout(12000),
    });
    const body = Buffer.from(await source.arrayBuffer());
    response.writeHead(source.status, {
      'Content-Length': body.length,
      'Content-Type': source.headers.get('content-type') ?? 'application/octet-stream',
    }).end(body);
  } catch {
    if (!response.headersSent) response.writeHead(502);
    response.end();
  }
}).listen(Number(port), '127.0.0.1');
